 "content": "def transform(grid):
    """Copy each horizontal border sequence to every isolated matching marker."""
    out = [row[:] for row in grid]
    h = len(grid)
    w = len(grid[0]) if h else 0

    # A multi-cell horizontal nonzero run is a color sequence/template.
    templates = []
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == 0:
                c += 1
                continue
            start = c
            while c < w and row[c] != 0:
                c += 1
            if c - start >= 2:
                templates.append((row[start:c], r, start))

    # Isolated nonzero cells are markers; align their color with its position
    # in the matching template, clipping naturally at the grid edges.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0:
                continue
            neighbors = sum(
                0 <= rr < h and 0 <= cc < w and grid[rr][cc] != 0
                for rr, cc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1))
            )
            if neighbors:
                continue
            matches = [(seq, seq.index(color)) for seq, _, _ in templates if color in seq]
            if not matches:
                continue
            # Puzzle templates use distinct marker colors; in a tie, the
            # closest template is the best local association.
            seq, idx = min(matches, key=lambda item: min(
                abs(r-tr) + abs(c-(tc+j))
                for t, tr, tc in templates if t == item[0]
                for j, value in enumerate(t) if value == color
            ))
            left = c - idx
            for j, value in enumerate(seq):
                cc = left + j
                if 0 <= cc < w:
                    out[r][cc] = value
    return out
